            '<a class="title" href="' + it.url + '" target="_blank" rel="noopener">' + it.title + "</a>" +
            '<div class="desc">' + it.desc + "</div>" +
            '<div class="tags">' + tags + "</div>" +
            '<div class="meta"><a href="' + it.url + '" target="_blank" rel="noopener">' + it.host + "</a>" +
              "<span>Saved " + it.saved + "</span></div>" +
          "</div>" +
          '<button class="rename" data-id="' + it.id + '">Rename</button>';
      }
      lib.appendChild(li);
    });
    document.querySelectorAll(".rename").forEach(btn => {
      btn.addEventListener("click", () => {
        const it = items.find(x => x.id == btn.dataset.id);
        const next = prompt("Rename this link:", it.title);
        if (next !== null && next.trim()) { it.title = next.trim(); render(); }
      });
    });
  }

  function save() {
    const input = document.getElementById("url");
    const raw = input.value.trim();
    if (!raw) return;
    const url = normUrl(raw);
    const it = { id: ++seq, url: url, host: hostOf(url), loading: true, saved: timeNow() };
    items.unshift(it);
    input.value = "";
    input.focus();
    render();
    // Simulate the automatic title/description fetch.
    setTimeout(() => {
      const meta = fetchMeta(url);
      it.loading = false; it.title = meta.t; it.desc = meta.d;
      render();
    }, 650);
  }

  document.getElementById("saveBtn").addEventListener("click", save);
  document.getElementById("url").addEventListener("keydown", e => {
    if (e.key === "Enter") save();
  });

  render();
  document.body.setAttribute("data-harness-ready", "true");
</script>
</body>
</html>
</content>

