<header>
  <h1>Link Library</h1>
  <span class="tag">Prototype</span>
</header>
<main>
  <div class="saver">
    <label for="url">Save a link</label>
    <div class="row">
      <input id="url" type="text" placeholder="Paste a web address, e.g. https://example.com/article" autocomplete="off">
      <button id="saveBtn">Save</button>
    </div>
  </div>
  <div class="tabs" id="tabs">
    <button class="tab active" data-view="library">Library</button>
    <button class="tab" data-view="toread">Reading list</button>
    <button class="tab" data-view="archive">Archive</button>
  </div>
  <div class="toolbar">
    <input id="search" type="search" placeholder="Search your library — title, note, site, or tag…" autocomplete="off">
    <label class="sortwrap">Sort:
      <select id="sort">
        <option value="new">Newest first</option>
        <option value="old">Oldest first</option>
        <option value="title">Title A–Z</option>
      </select>
    </label>
  </div>
  <div class="dup" id="dupNotice"></div>
  <div class="dup saveerr" id="saveError"></div>
  <div class="bulkbar" id="bulkbar">
    <span class="bulkcount" id="bulkCount"></span>
    <span class="bulkscope" id="bulkScope"></span>
    <span class="bulkspacer"></span>
    <button class="act" data-bulk="toread">☆ Read later</button>
    <button class="act" data-bulk="read">✓ Mark read</button>
    <button class="act" data-bulk="tag">＋ Add tag</button>
    <button class="act" data-bulk="untag">－ Remove tag</button>
    <button class="act" data-bulk="archive" id="bulkArchive">🗄 Archive</button>
    <button class="act" data-bulk="delete">🗑 Delete</button>
    <button class="act" data-bulk="clear">Clear</button>
  </div>
  <p class="count" id="count"></p>
  <p class="selectall" id="selectAll"></p>
  <ul class="library" id="library"></ul>
</main>

<div class="overlay" id="editOverlay">
  <div class="snap" style="max-width:540px">
    <div class="snaphead"><div><h3>Edit link</h3></div><button class="close" id="editClose">&times;</button></div>
    <div class="snapbody">
      <label class="fldlabel">Title</label>
      <input id="edTitle" class="fld">
      <label class="fldlabel">Address (web page or file)</label>
      <input id="edUrl" class="fld">
      <label class="fldlabel">Description</label>
      <textarea id="edDesc" class="fld"></textarea>
      <div class="fld-error" id="edError"></div>
      <div class="btnrow">
        <button class="act" id="editCancel">Cancel</button>
        <button class="primary" id="editSave">Save changes</button>
      </div>
    </div>
  </div>
</div>

<div class="overlay" id="confirmOverlay">
  <div class="snap" style="max-width:460px">
    <div class="snapbody">
      <h3 id="cfTitle" style="margin-top:0">Delete this link?</h3>
      <p id="cfMsg" style="color:#444b5c"></p>
      <div class="btnrow">
        <button class="act" id="cfCancel">Cancel</button>
        <button class="danger" id="cfOk">Delete permanently</button>
      </div>
    </div>
  </div>
</div>

<div class="overlay" id="overlay">
  <div class="snap">
    <div class="snaphead">
      <div>
        <span class="cap" id="snapCap"></span>
        <h3 id="snapUrl"></h3>
      </div>
      <button class="close" id="snapClose">&times;</button>
    </div>
    <div class="banner">You're viewing a preserved copy saved in your library — not the live page.</div>
    <div class="snapbody" id="snapBody"></div>
  </div>
</div>
